contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount to stake/withdraw, and the staking token holder must have approved c to transfer
    // We assume msg.sender of stakeFor is this contract when calling c.stakeFor, so tests should model typical flow
    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be >0");

        // Read before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 contractBalanceBefore = address(c).balance;

        bool stakeReverted;
        // Try to stake: call stakeFor(address _for, uint256 _amount)
        // Must call as top-level statement
        try c.stakeFor(address(this), amount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // If stake reverted, then nothing changed; assert that totals remain equal
        if (stakeReverted) {
            assert(c.totalSupply() == totalBefore && c.balanceOf(address(this)) == balBefore);
            return;
        }

        // After successful stake, attempt withdraw of same amount (without claiming rewards)
        bool withdrawReverted;
        try c.withdraw(amount, false) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // General property: if stake succeeded and withdraw did not revert, totalSupply and balanceOf revert to before values
        // Also ensure that if withdraw succeeded, contract's ether balance is unchanged (we didn't route ETH)
        assert((withdrawReverted == false) ? (c.totalSupply() == totalBefore && c.balanceOf(address(this)) == balBefore && address(c).balance == contractBalanceBefore) : true);
    }

    receive() external payable {}
 }

