contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function driving the property test
    function run(uint256 amount) public payable {
        // require a positive amount to avoid trivial zero-stake behavior
        require(amount > 0, "amount>0");

        // observe before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 ethBefore = address(c).balance;

        bool stakeReverted;
        try c.stakeFor(address(this), amount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        if (stakeReverted) {
            // If stake reverted we cannot assert the post-conditions; require nothing more and assert a non-trivial fact: stake reverted implies no increase in observed token balance or totalSupply (they must be unchanged)
            // Note: call view functions to read current values
            uint256 totalNow = c.totalSupply();
            uint256 balNow = c.balanceOf(address(this));
            uint256 ethNow = address(c).balance;
            // general reasonable expectation: if stake reverted then observable numeric state did not increase compared to before
            assert(totalNow <= totalBefore && balNow <= balBefore && ethNow == ethBefore);
            return;
        }

        // Stake succeeded. Now attempt withdraw of the same amount without claiming rewards.
        bool withdrawReverted;
        try c.withdraw(amount, false) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // After successful stake, withdrawing same amount must not revert and must restore totals and balances and not change contract ETH
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 ethAfter = address(c).balance;

        assert(withdrawReverted == false && totalAfter == totalBefore && balAfter == balBefore && ethAfter == ethBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry with parameters to drive stakeFor
    function run(address staker, uint256 amount) public payable {
        require(staker != address(0));
        require(amount > 0);

        // Ensure this contract has enough of the staking token to transfer to c
        // We cannot mint tokens here; but the checker deploys c with staking token set
        // We'll attempt to stake by calling stakeFor: it will call stakingToken.safeTransferFrom(msg.sender,...)
        // msg.sender for calls from this contract is this contract. The call may revert if allowance/balance insufficient.

        // read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);

        // attempt stakeFor from this contract to stake on behalf of `staker`
        bool reverted;
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(staker);

        // General rule: if the stakeFor call did not revert, the totalSupply and the staker's balance increased by exactly `amount`.
        // If it reverted, they must be unchanged.
        assert(
            (reverted && afterTotal == beforeTotal && afterBalance == beforeBalance) ||
            (!reverted && afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount)
        );
    }

    receive() external payable {}
}

