contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: distributor address (must equal rewardDistributor to succeed), reward token address, amount
    // We will try the call and observe whether it reverts. If it succeeds, then periodFinish >= block.timestamp and token balance increased by amount.
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount must be >0");

        // Preconditions: add rewardToken first as owner (constructor of C set owner to this deployer, which is the test deployer of C), but we cannot assume test is owner.
        // We will observe current reward period finish and token balance, then attempt notifyRewardAmount as msg.sender = this (InvMutTest is caller to c).

        // Read observable before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        // Try calling notifyRewardAmount. It requires msg.sender == rewardDistributor and that rewardToken is known and amount>0.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // If call succeeded (not reverted) then rewardDistributor check and token-known checks passed and transfer succeeded.
        // Rule: if notifyRewardAmount did not revert then periodFinish is >= block.timestamp and contract token balance increased by amount.
        assert(reverted || (uint256(afterFinish) >= block.timestamp && afterBalance == beforeBalance + amount));
    }

    // Minimal IERC20 view used to read balances
    receive() external payable {}
}

