contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: distributor must attempt to call notifyRewardAmount; token is any address (should be added earlier by owner), amount > 0
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // Record pre-state visible via public getters
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBal = IERC20(rewardToken).balanceOf(address(c));

        // Try to call notifyRewardAmount from distributor by using c.notifyRewardAmount via low-level call from this contract
        // But only the rewardDistributor address is allowed; our call will be from this contract, so simulate by first setting rewardDistributor if this contract is owner.
        // We can't assume owner, so we attempt the call and record whether it reverted.

        bool reverted;
        // We must call as msg.sender == distributor; to simulate different msg.sender, we require distributor == address(this) OR just call and observe revert.
        // The contract c expects msg.sender == rewardDistributor; since we cannot change msg.sender to arbitrary address in a single contract, we instead detect whether the call reverts (not distributor) or succeeds.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = IERC20(rewardToken).balanceOf(address(c));

        // General rule: if call did not revert then
        // 1) afterFinish >= block.timestamp (i.e. periodFinish set to future or now)
        // 2) afterBal == beforeBal + amount
        // If it reverted then nothing is required about state (we only assert implication)
        assert(reverted || (afterFinish >= uint40(block.timestamp) && afterBal == beforeBal + amount));
    }

    receive() external payable {}
}

