contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: staker is the address from which tokens will be transferred (msg.sender of token.transferFrom)
    // We cannot control external accounts here; the InvMutTest contract will call c.stakeFor, so msg.sender will be this contract.
    // amount is the stake amount; caller must approve this contract's token balance beforehand in the setup (external to this test harness).
    function run(uint256 amount) public payable {
        require(true);

        // Read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 tokenBalBefore = token.balanceOf(address(c));

        // Attempt to stakeFor this contract using stakeFor(address _for, uint256 _amount)
        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 tokenBalAfter = token.balanceOf(address(c));

        // General invariant:
        // If the stakeFor call reverted then none of the observed balances on c changed.
        // If it did not revert then totalSupply and the user's balance increased by exactly `amount`,
        // and the token balance held by c increased by exactly `amount`.
        assert(
            (reverted && totalAfter == totalBefore && balAfter == balBefore && tokenBalAfter == tokenBalBefore)
