        // Record c's observable state before staking
        uint256 totalBefore = c.totalSupply();
        uint256 myBalBefore = c.balanceOf(address(this));
        uint256 contractBalBefore = tokenI.balanceOf(address(c));

        // Stake: call stakeFor via stakeFor (public) — stakeFor will call safeTransferFrom so this contract must have approved
        c.stakeFor(address(this), stakeAmount);

        // After staking observables
        uint256 totalAfterStake = c.totalSupply();
        uint256 myBalAfterStake = c.balanceOf(address(this));
        uint256 contractBalAfterStake = tokenI.balanceOf(address(c));

        // Preconditions: staking should have increased totalSupply and our balance by stakeAmount and token balance of contract increased by same
        // But stakeFor may revert in some edge cases; ensure it succeeded by checking effect
        require(totalAfterStake >= totalBefore, "stake did not increase totalSupply");
        require(myBalAfterStake >= myBalBefore, "stake did not increase my balance");
        require(contractBalAfterStake >= contractBalBefore, "contract token balance not increased");

        // Now attempt withdraw. Record state before withdraw
        uint256 totalBeforeWithdraw = totalAfterStake;
        uint256 myBalBeforeWithdraw = myBalAfterStake;
        uint256 contractBalBeforeWithdraw = tokenI.balanceOf(address(c));
        uint256 selfTokenBalBefore = tokenI.balanceOf(address(this));

        bool reverted;
        // withdraw is called as this contract (since run invoked by external), so c.withdraw will act on msg.sender = this test contract
        try c.withdraw(withdrawAmount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after withdraw attempt
        uint256 totalAfterWithdraw = c.totalSupply();
        uint256 myBalAfterWithdraw = c.balanceOf(address(this));
        uint256 contractBalAfterWithdraw = tokenI.balanceOf(address(c));
        uint256 selfTokenBalAfter = tokenI.balanceOf(address(this));

        // Assert general invariant: if withdraw succeeded then totalSupply decreased by withdrawAmount and our c.balance decreased by withdrawAmount and token moved from c to us by withdrawAmount; if it reverted then all those observable values are unchanged.
        assert(
            (reverted && totalAfterWithdraw == totalBeforeWithdraw && myBalAfterWithdraw == myBalBeforeWithdraw && contractBalAfterWithdraw == contractBalBeforeWithdraw && selfTokenBalAfter == selfTokenBalBefore)
            || (!reverted && totalAfterWithdraw + withdrawAmount == totalBeforeWithdraw && myBalAfterWithdraw + withdrawAmount == myBalBeforeWithdraw && contractBalBeforeWithdraw == contractBalAfterWithdraw + withdrawAmount && selfTokenBalAfter == selfTokenBalBefore + withdrawAmount)
        );
    }

    receive() external payable {}
}

