        // approach: If doAdd is true, call addReward as owner requirement will revert (since this contract isn't owner). We must avoid reverting during setup.
        // So we will not call any state-changing owner-only functions. Instead, we will read the prior periodFinish, then attempt notifyRewardAmount
        // capturing whether it reverts. The property we assert is conditional: if notifyRewardAmount succeeds, then the new periodFinish >= block.timestamp
        // and new periodFinish >= oldPeriodFinish. If it reverted, we assert that it reverted only when msg.sender != rewardDistributor or other preconditions failed.

        // Read prior periodFinish via view (returns 0 for unknown token if not added)
        uint40 oldFinish = c.rewardPeriodFinish(rewardToken);

        bool reverted;
        // Attempt call as this contract; to succeed require this contract equals c.rewardDistributor() and token was added and amount>0 and approve done.
        // We cannot approve tokens here (unknown ERC20). So many calls will revert; we capture that.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 newFinish = c.rewardPeriodFinish(rewardToken);

        // The general rule we assert:
        // If notifyRewardAmount succeeded (not reverted), then newFinish >= block.timestamp and newFinish >= oldFinish.
        // If it reverted, then at least one of the external preconditions likely failed: msg.sender != rewardDistributor OR amount == 0 OR token unknown.
        // We can observe rewardDistributor and require that if it reverted but this contract was the distributor and amount>0 and token was added (oldFinish != 0), that's a violation.
        address dist = c.rewardDistributor();

        bool thisIsDistributor = (dist == address(this));
        bool amountPositive = (amount > 0);
        bool tokenKnown = (oldFinish != 0);

        // Build the asserted condition as a single boolean expression.
        // If not reverted: newFinish >= uint40(block.timestamp) && newFinish >= oldFinish
        // If reverted: at least one of the expected preconditions failed (thisIsDistributor==false || !amountPositive || !tokenKnown)
        bool okIfSucceeded = (!reverted) ? (uint256(newFinish) >= block.timestamp && uint256(newFinish) >= uint256(oldFinish)) : true;
        bool okIfReverted = reverted ? ( (!thisIsDistributor) || (!amountPositive) || (!tokenKnown) ) : true;

        assert(okIfSucceeded && okIfReverted);
    }

    // receive to accept ETH if ever needed by C in other scenarios
    receive() external payable {}
}

