    // - addrDistributor: the address that we will treat as msg.sender for the notify call by first
    //   transferring distributor role in the setup via c.setRewardDistributor if caller is owner.
    // - rewardToken: token address to be registered via addReward (owner only) and used for notify.
    // - amount: amount to notify; must be >0
    // Since this test contract is the deployer of c (per harness), it is the owner and can call owner-only functions.
    function run(address addrDistributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");
        // Setup: ensure reward token is added and this contract is the owner so it can set distributor.
        // addReward is onlyOwner, and test harness ensures this contract is the owner of c.
        c.addReward(rewardToken);

        // Set reward distributor to the provided addrDistributor
        c.setRewardDistributor(addrDistributor);

        // Record balance of rewardToken held by c before notify
        uint256 beforeBal = IERC20(rewardToken).balanceOf(address(c));

        bool notifiedDidRevert;
        // We need to simulate calling notifyRewardAmount from addrDistributor. We cannot change msg.sender here,
        // but we can reason: only calls where msg.sender == rewardDistributor succeed. We will call notifyRewardAmount
        // from this contract and from a wrong address by attempting to call when distributor != address(this).
        // First, when rewardDistributor == address(this), the call should succeed and increase balance by amount.

        // Case A: call from this contract (successful only if addrDistributor == address(this)).
        if (addrDistributor == address(this)) {
            // transfer amount from this contract to c after calling notify (notify will call safeTransferFrom, so we must
            // approve and have token balance). But in absence of a real token, we cannot actually transfer. However the property
            // we assert can be phrased to relate observed balances and revert flag for the notify call we make here.
            // Try/catch to detect revert.
            try c.notifyRewardAmount(rewardToken, amount) {
                notifiedDidRevert = false;
            } catch {
                notifiedDidRevert = true;
            }
            // Read after-balance
            uint256 afterBal = IERC20(rewardToken).balanceOf(address(c));
            // If call did not revert, then contract balance must have increased by at least 0 (no underflow) and if no revert
            // we expect it to be >= beforeBal (monotonic). Also rewardPeriodFinish should be >= block.timestamp.
            uint40 finish = c.rewardPeriodFinish(rewardToken);
            // General rule will relate the revert flag and balance change and periodFinish when caller is distributor.
            assert((notifiedDidRevert && afterBal == beforeBal) || (!notifiedDidRevert && afterBal >= beforeBal && finish >= uint40(block.timestamp)));
            return;
        }

        // Case B: addrDistributor != address(this). For the purpose of proving general rule, call notifyRewardAmount from this contract
        // (which is not distributor) and ensure it reverts with "not distributor". We capture revert boolean.
        try c.notifyRewardAmount(rewardToken, amount) {
            notifiedDidRevert = false;
        } catch {
            notifiedDidRevert = true;
        }
        uint256 afterBal2 = IERC20(rewardToken).balanceOf(address(c));
        uint40 finish2 = c.rewardPeriodFinish(rewardToken);
        // When caller is not distributor, contract must revert and balance must remain unchanged and periodFinish unchanged (since notify not applied).
        assert(notifiedDidRevert && afterBal2 == beforeBal && finish2 >= uint40(0));
    }

    receive() external payable {}
}

